import './index.scss';

const CartTableItem = ({ product }) => {
    const images = {
        cabbage: cabbage,
        corn: corn,
        spinach: spinach,
    };
    const imageSrc = images[product.img];
    return (
        <div className='cart-item' key={product.id}>
            <div className='cart-item__image'>
                <img src={mageSrc} alt="" />
            </div>
        </div>
    )
}

export default CartTableItem
